/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Functions: ImportSummary
 * Internal
 *   Types: Step
 *   Functions: valueAt, valueText
 *   Constants: LookupBox, CandidateChooser, ImportAnalysisConfirmation
 * @end-catalog */

import { lazy, Suspense, useEffect, useId, useState, useSyncExternalStore } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { useLocalization } from '../../localization/LocalizationProvider';
import type { MessageKey } from '../../localization/contract';
import { useAdminAccess, useAdminText } from './AdminAccess';
import { importPath, type ImportDetail, type ImportDraftV2 } from './adminApi';
import { adminWorkspace } from './adminWorkspace';
import { entriesByline } from './artistEntriesByline';
import { approvalTrackOrder } from './importTrackOrder';
import type { ImportDraftChange } from './importDraftPatch';
import { lunaTicksKey, suggestionPath, ticked } from './importLunaTicks';
import { importSummaryQuery } from './importSummaryQuery';
import { reviewValueText } from './reviewValueText';
import { useOnline } from './useAdminOnline';
import type { AdminMutation } from './useAdminMutation';
import type { ImportUploadQueueView } from './useImportUploadQueue';
import styles from './adminStyles';

// The name box, the candidate chooser and the Analyze confirmation load only when this summary shows them.
const LookupBox = lazy(() => import('./LookupBox').then(module => ({ default: module.LookupBox })));
const CandidateChooser = lazy(() => import('./CandidateChooser').then(module => ({ default: module.CandidateChooser })));
const ImportAnalysisConfirmation = lazy(() => import('./ImportAnalysisConfirmation').then(module => ({ default: module.ImportAnalysisConfirmation })));

type Step = 'retry' | 'luna';
/** A lookup path's saved value, or the shown one with `draft`. */
const valueAt = (draft: ImportDraftV2, path: string): unknown => {
  const [scope, first, second] = path.split('.');
  return scope === 'album' ? (draft.album as Record<string, unknown>)[first] : (draft.tracks.find(track => track.slotId === first) as Record<string, unknown> | undefined)?.[second];
};
/** Artist entries read as their byline, a label as its name and anything else as review text. */
const valueText = (value: unknown) => Array.isArray(value) ? entriesByline(value) || '—' : value && typeof value === 'object' && 'name' in value ? String(value.name) : reviewValueText(value);

/**
 * The Review and publish summary an import opens on, above its Draft, Review, Files and Publish sections. The server decides what
 * it shows as needing an answer or holding Publish (the lookup view's `needsAnswer` and the summary state, identity rows to answer
 * in Review included); this component only presents it, adding this browser's own upload queue and, for the placeholder-only
 * notice, a primary Artist entry the unsaved changes add, since Publish includes them. It shows the metadata lookup status with
 * its next step (a free retry or Luna, per the owner's next-step rules; no lookup step where this server cannot run lookup), the
 * name box, a tie or conflict that needs an answer, the values flagged as resting on file tags, an artist mismatch and the Luna
 * suggestions with their ticks (the administrator's toggles are kept in the workspace for the confirmation; an append marks its
 * Album ones as not applied), and folds every row that needs no answer. Its Publish opens the media panel's one-step
 * confirmation. Owner rules: docs/business-rules.md (Administrator Album Imports, Review and publish summary; Administrator
 * Metadata Lookup).
 */
export function ImportSummary({ item, operation, uploads, disabled, publishDisabled, approval, onPublish }: {
  item: ImportDetail; operation: AdminMutation; uploads: ImportUploadQueueView; disabled: boolean; publishDisabled: boolean;
  approval: { draft: ImportDraftV2; changes: ImportDraftChange[] }; onPublish: () => void;
}) {
  const t = useAdminText(), { t: shared } = useLocalization(), access = useAdminAccess(), online = useOnline(), client = useQueryClient(), id = useId();
  const query = useQuery(importSummaryQuery(access, item, online)), data = query.data, lookup = data?.lookup ?? null, summary = data?.summary;
  const [toggles, setToggles] = useState<Record<string, boolean>>(() => adminWorkspace.buffer(lunaTicksKey(item.id)) ?? {});
  const [analyzing, setAnalyzing] = useState(false);
  const project = ['admin-imports', access.viewerId, access.epoch, access.generation, item.id], failed = useSyncExternalStore(operation.subscribe, operation.getSnapshot).error;
  // This read saw a newer saved project (an applied lookup or another automatic write): the page reads it too.
  useEffect(() => { if (data && (data.revision > item.revision || data.valueRevision > item.valueRevision)) void client.invalidateQueries({ queryKey: project, exact: true }); }, [data]);
  // A lookup refusal means the lookup changed or ended elsewhere: the project and this summary are read again.
  useEffect(() => { if (failed?.startsWith('lookup_')) void client.invalidateQueries({ queryKey: project }); }, [failed]);
  const path = importPath(item.id), draft = approval.draft, changed = new Set(approval.changes.map(change => change.path)), append = Boolean(summary?.append);
  const run = (action: string, payload: object = {}) => operation.run(`${path}/${action}`, 'POST', { expectedRevision: item.revision, ...payload });
  const label = (target: string) => {
    const [scope, slot, field] = target.split('.');
    const name = t(`field.${scope === 'album' ? slot : field}`);
    return scope === 'album' ? name : t('summary.track_field', { position: item.draft.tracks.findIndex(track => track.slotId === slot) + 1, field: name });
  };
  const role = (value: string) => shared(`catalog.credit.${value}` as MessageKey);
  // The status, the next step and the step beside it (owner rules: Administrator Metadata Lookup, next-step bullet). Without a
  // run, lookup is not configured here, waits for uploads, or did not start (its trigger failed); a retry or a name needs it configured.
  const applied = lookup?.applied, tie = Boolean(lookup?.needsAnswer.tie), available = summary?.lookupAvailable !== false;
  const [status, next, beside]: [string, Step | null, Step | null] = !lookup ? [!available ? 'lookup.not_configured' : summary?.waiting.uploads ? 'lookup.not_run' : 'lookup.not_started', summary?.waiting.uploads && available ? null : 'luna', null]
    : lookup.state === 'queued' || lookup.state === 'running' ? ['lookup.active', null, null]
    : lookup.state === 'retrying' ? ['lookup.retrying', 'retry', 'luna']
    : lookup.state === 'unavailable' ? [lookup.issue === 'notConfigured' ? 'lookup.not_configured' : 'lookup.unavailable', 'luna', 'retry']
    : lookup.state !== 'complete' ? [`lookup.${lookup.state}`, 'retry', 'luna']
    : lookup.outcome === 'noRelease' || lookup.outcome === 'noQuery' ? [lookup.outcome === 'noQuery' ? 'lookup.no_query' : 'lookup.no_release', 'luna', null]
    : tie ? ['lookup.tie', null, null]
    : applied?.run === lookup.run && applied.choice !== 'none' ? ['lookup.applied', null, null]
    : lookup.groups.length ? ['lookup.applied_none', null, null]
    // Candidates whose details could not be fetched are no proof that nothing matches.
    : lookup.candidates.some(candidate => candidate.status === 'incomplete') ? ['lookup.incomplete', 'retry', 'luna']
    : [applied?.run === lookup.run ? 'lookup.applied_none' : 'lookup.no_match', 'luna', null];
  const steps = [next, beside].filter((kind): kind is Step => Boolean(kind) && (kind !== 'retry' || available));
  const release = lookup?.candidates.find(candidate => candidate.key === applied?.candidateKey)?.title ?? '—';
  const luna = access.analysis && item.capabilities.analysis && !['queued', 'running'].includes(item.analysis.state) && item.analysis.issue !== 'providerOutcomeUnknown' && Boolean(summary?.analysis.runs);
  const step = (kind: Step, primary: boolean) => <button key={kind} type="button" className={`${styles.button} ${primary ? styles.primary : ''}`} disabled={disabled || (kind === 'luna' && !luna)}
    onClick={() => kind === 'retry' ? run('lookup/retry') : setAnalyzing(true)}>{t(kind === 'retry' ? 'lookup.retry' : 'lookup.luna')}</button>;
  const needed = new Set(lookup?.needsAnswer.conflicts ?? []), conflicts = applied?.conflicts ?? [], open = conflicts.filter(conflict => needed.has(conflict.path));
  const resolve = (target: string, answer: 'mine' | 'lookup') => run('lookup/resolve', { run: applied!.run, candidateKey: applied!.candidateKey, answers: [{ path: target, answer, base: valueAt(item.draft, target) }] });
  // Values resting only on file tags (not on the applied candidate, not changed here) are flagged and never folded.
  const fromTags = item.automaticPaths.filter(target => !item.lookupPaths.includes(target) && !changed.has(target) && !(append && target.startsWith('album.')));
  const ticks = new Map(summary?.luna.map(entry => [entry.id, entry.tick]));
  const suggestions = item.suggestions.filter(suggestion => suggestion.decision === 'pending' && ticks.has(suggestion.id) && ticks.get(suggestion.id) !== 'resolved');
  const on = suggestions.filter(suggestion => ticked(suggestion, ticks.get(suggestion.id), toggles, changed)).map(suggestion => suggestion.id);
  const toggle = (suggestion: string, value: boolean) => { const next = { ...toggles, [suggestion]: value }; setToggles(next); adminWorkspace.retain(lunaTicksKey(item.id), next, access); };
  // This browser's own upload queue holds Publish too, before the server has seen its transfers.
  const waiting = summary ? (['uploads', 'lookup', 'analysis'] as const).filter(work => summary.waiting[work] || (work === 'uploads' && uploads.running)) : [];
  const identities = summary?.identityAnswers ?? 0, answers = (tie ? 1 : 0) + open.length + identities, locked = ['preparing', 'needsAttention', 'complete'].includes(item.publication);
  const placeholder = summary?.placeholderOnly && !draft.album.artists.some(entry => entry.role === 'primary');
  const notApplied = (text: string) => append ? `${text} · ${t('publication.not_applied')}` : text;
  const row = (target: string, text: string) => <div key={target}><dt>{label(target)}</dt><dd>{text}</dd></div>;
  const cover = item.selectedCoverSlotId;
  return <section aria-labelledby={`${id}-title`} className={styles.panel}>
    <header className={styles.sectionHeader}><h2 id={`${id}-title`}>{t('summary.title')}</h2></header>
    {query.isPending && <p role="status">{t('common.loading')}</p>}
    {query.isError && <p role="status">{t('common.error')}</p>}
    {placeholder && <p role="status" className={styles.error}>{t('summary.placeholder_only')}</p>}
    {data && <>
      <p role="status">{t(status, { title: release })}</p>
      {lookup && lookup.staleFiles.length > 0 && <p>{t('lookup.stale_files', { count: lookup.staleFiles.length })}</p>}
      {steps.length > 0 && <div className={styles.actions}>{steps.map((kind, index) => step(kind, !index))}</div>}
      {available && <Suspense fallback={null}><LookupBox key={lookup?.run ?? 0} lookup={lookup} rootLabel={item.manifest.rootLabel} disabled={disabled} onSubmit={(kind, text) => run('lookup', { kind, text })} /></Suspense>}
      {lookup?.state === 'complete' && lookup.candidates.length > 0 && <Suspense fallback={null}><CandidateChooser lookup={lookup} disabled={disabled} onChoose={key => run('lookup/choose', { run: lookup.run, candidateKey: key })} /></Suspense>}
      {open.length > 0 && <section aria-labelledby={`${id}-conflicts`}><h3 id={`${id}-conflicts`}>{t('summary.conflicts')}</h3><ul className={styles.cards}>{open.map(conflict =>
        <li key={conflict.path} className={styles.card}><strong id={`${id}-${conflict.path}`}>{label(conflict.path)}</strong>
          <dl className={styles.diff}><div><dt>{t('summary.yours')}</dt><dd>{valueText(valueAt(item.draft, conflict.path))}</dd></div><div><dt>{t('summary.lookup_value')}</dt><dd>{valueText(conflict.lookup)}</dd></div></dl>
          <div className={styles.actions}>{(['mine', 'lookup'] as const).map(answer => <button key={answer} type="button" className={styles.button} disabled={disabled} aria-describedby={`${id}-${conflict.path}`}
            onClick={() => resolve(conflict.path, answer)}>{t(answer === 'mine' ? 'summary.keep_mine' : 'summary.use_lookup')}</button>)}</div></li>)}</ul></section>}
      {(fromTags.length > 0 || (lookup?.preselection?.artistMismatch && applied?.choice === 'preselected' && applied.run === lookup.run)) && <ul aria-label={t('summary.flagged')}>
        {lookup?.preselection?.artistMismatch && applied?.choice === 'preselected' && applied.run === lookup.run && <li>{t('summary.artist_mismatch')}</li>}
        {fromTags.map(target => <li key={target}>{`${label(target)}: ${valueText(valueAt(draft, target))} · ${t('publication.tags_only')}`}</li>)}</ul>}
      {suggestions.length > 0 && <fieldset className={styles.editor}><legend>{t('summary.luna')}</legend><p className={styles.muted}>{t('summary.luna_help')}</p>
        {suggestions.map(suggestion => {
          const target = suggestionPath(suggestion), blocked = ticks.get(suggestion.id) === 'conflict' || changed.has(target);
          return <div key={suggestion.id}><label className={styles.check}><input type="checkbox" checked={on.includes(suggestion.id)} disabled={disabled || blocked} onChange={event => toggle(suggestion.id, event.target.checked)} />
            {`${label(target)}: ${valueText(valueAt(draft, target))} → ${valueText(suggestion.value)} · ${t('summary.luna_mark')}${append && suggestion.scope === 'album' ? ` · ${t('publication.not_applied')}` : ''}`}</label>
            {blocked && <p className={styles.muted}>{t('review.conflict')}</p>}</div>;
        })}
        <div className={styles.actions}><button type="button" className={styles.button} disabled={disabled} onClick={() => run('adopt', { generation: item.analysis.generation, selectedIds: on, rejectIds: suggestions.map(suggestion => suggestion.id).filter(value => !on.includes(value)) })}>{t('summary.luna_apply')}</button></div>
      </fieldset>}
      <details className={styles.details}><summary>{t('summary.values')}</summary><dl>
        {!fromTags.includes('album.title') && row('album.title', notApplied(draft.album.title || t('common.untitled')))}
        {!fromTags.includes('album.artists') && <div><dt>{t('field.artists')}</dt><dd>{notApplied(entriesByline(draft.album.artists) || '—')}<ol>{draft.album.artists.map(entry => <li key={entry.key}>{[entry.name, role(entry.role),
          entry.joinPhrase && t('publication.join_phrase', { phrase: entry.joinPhrase })].filter(Boolean).join(' · ')}</li>)}</ol></dd></div>}
        {!fromTags.includes('album.label') && row('album.label', notApplied(draft.album.label?.name ?? t('publication.no_label')))}
        {!fromTags.includes('album.releaseDate') && row('album.releaseDate', notApplied(reviewValueText(draft.album.releaseDate)))}
        <div><dt><label htmlFor={`${id}-visibility`}>{t('field.visibility')}</label></dt><dd><select id={`${id}-visibility`} value={draft.album.visibility} disabled={disabled || append || locked}
          onChange={event => operation.run(path, 'PATCH', { expectedRevision: item.revision, changes: [{ path: 'album.visibility', base: item.draft.album.visibility, value: event.target.value }] })}>
          {(['public', 'hidden'] as const).map(value => <option key={value} value={value}>{t(`field.${value}`)}</option>)}</select>{append && ` · ${t('publication.not_applied')}`}</dd></div>
        <div><dt>{t('layout.selected_cover')}</dt><dd>{notApplied(cover === null ? t('media.no_cover') : cover === 'cover' ? t('media.manual_cover') : t('media.cover_candidate'))}</dd></div>
        <div><dt>{t('summary.tracks')}</dt><dd><ol>{approvalTrackOrder(draft.tracks).map(track => <li key={track.slotId}>{[t('publication.track_position', { disc: String(track.discNumber ?? 1), track: track.trackNumber === null ? '—' : String(track.trackNumber) }), track.title || t('common.untitled')].join(' · ')}</li>)}</ol></dd></div>
        <div><dt>{t('summary.identities')}</dt><dd>{t('summary.identities_saved', { count: item.decisions.length })}</dd></div>
        <div><dt>{t('stage.upload')}</dt><dd>{t('summary.uploads', { ready: item.upload.ready, total: item.upload.total })}{uploads.running ? ` · ${t('upload.uploading')}` : ''}</dd></div>
        {conflicts.filter(conflict => !needed.has(conflict.path)).map(conflict => row(conflict.path, `${valueText(conflict.lookup)} · ${t(conflict.answer === 'lookup' ? 'summary.used_lookup' : conflict.answer === 'mine' ? 'summary.kept_mine' : 'publication.not_applied')}`))}
      </dl></details>
      {!locked && <div className={styles.actions}><button type="button" className={`${styles.button} ${styles.primary}`} disabled={publishDisabled || !summary || waiting.length > 0 || answers > 0 || placeholder} onClick={onPublish}>{t('summary.publish')}</button></div>}
      {waiting.map(work => <p key={work} role="status">{t(`summary.waiting_${work}`)}</p>)}
      {answers > 0 && <p role="status">{t('summary.needs_answers', { count: answers })}</p>}
      {identities > 0 && <p>{t('summary.identity_answers', { count: identities })}</p>}
    </>}
    {analyzing && <Suspense fallback={null}><ImportAnalysisConfirmation item={item} disabled={disabled || !luna} onClose={() => setAnalyzing(false)} onConfirm={() => { setAnalyzing(false); run('analyze'); }} /></Suspense>}
  </section>;
}
